# -*- coding: utf-8 -*-
"""Apply the v8 -> v9 edits (review findings) to manuscript_v8_ko.md and write manuscript_v9_ko.md.
Every replacement asserts that the old string occurs exactly once."""
import re, json, sys
SRC = 'manuscript_v8_ko.md'; DST = 'manuscript_v9_ko.md'
t = open(SRC, encoding='utf-8').read()
fails = []
def rep(old, new, n=1):
    global t
    c = t.count(old)
    if c != n:
        fails.append((c, old[:90])); return
    t = t.replace(old, new)
def ins_after(anchor, text):
    rep(anchor, anchor + text)

